  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 The Ascension and the Day of Pentecost$j$, $j${"readings": [{"title": "Acts 1 (King James Version)", "url": "/portal/bible/Acts/1"}, {"title": "Acts 2 (King James Version)", "url": "/portal/bible/Acts/2"}], "body": "Read Acts 1 and Acts 2 in the King James Version. Then read this lesson.\n\nThe book of Acts was written by Luke as a second volume to his Gospel. It tells how the good news spread from Jerusalem to Rome. Before Jesus returned to heaven, He told His followers to wait in Jerusalem for the promise of the Father and said that they would receive power and be witnesses. He was taken up, and a cloud received Him out of their sight. About one hundred and twenty believers waited and prayed. On the day of Pentecost they were all filled with the Holy Ghost and spoke with other tongues as the Spirit gave them utterance. Peter preached, the crowd asked what to do, and about three thousand souls were added to the church that day.\n\nKey words: Acts, witness, Pentecost, Holy Ghost, repentance.\n\nYour task: (1) Tell who wrote Acts and what the book is about. (2) Write Acts 1:8 in your own words. (3) Tell what Peter told the crowd to do in Acts 2:38 and how many people were added that day.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 2. The four Gospels showed us the life of Jesus. Now we open the book of Acts, which shows what Jesus continued to do through His church. Acts was written by Luke, the same man who wrote the Gospel of Luke, and it tells how the good news spread from Jerusalem all the way to Rome.\n\nBefore Jesus went back to heaven, He told His followers to stay in Jerusalem and wait for the promise of the Father. Then He gave them a mission. Acts 1:8 says, But ye shall receive power, after that the Holy Ghost is come upon you: and ye shall be witnesses unto me both in Jerusalem, and in all Judaea, and in Samaria, and unto the uttermost part of the earth. That verse is like a table of contents for the whole book. First Jerusalem, then Judaea and Samaria, and then the ends of the earth.\n\nRight after He said this, Jesus was lifted up, and a cloud received Him out of their sight. Two men in white told the disciples that this same Jesus would come again. The believers went back to an upper room, about one hundred and twenty of them, and they prayed together with one accord.\n\nThen came the day of Pentecost, a Jewish feast fifty days after Passover when Jerusalem was full of visitors. Acts 2:4 says, And they were all filled with the Holy Ghost, and began to speak with other tongues, as the Spirit gave them utterance. People from many nations heard the wonderful works of God in their own languages.\n\nPeter stood up and preached. He told the crowd about Jesus, whom they had crucified and whom God had raised from the dead. The people were pricked in their heart and asked what they should do. Acts 2:38 says, Repent, and be baptized every one of you in the name of Jesus Christ for the remission of sins, and ye shall receive the gift of the Holy Ghost. About three thousand souls were added that day. The church was born.\n\nYour task is to tell who wrote Acts, put Acts 1:8 in your own words, and tell what Peter told the crowd to do and how many were added. Then take the four question check.\n\nThe same Spirit who came at Pentecost is the promise of the Father for us today. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 The Ascension and the Day of Pentecost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Peter, Stephen and the Conversion of Saul$j$, $j${"readings": [{"title": "Acts 3 (King James Version)", "url": "/portal/bible/Acts/3"}, {"title": "Acts 4 (King James Version)", "url": "/portal/bible/Acts/4"}, {"title": "Acts 7 (King James Version)", "url": "/portal/bible/Acts/7"}, {"title": "Acts 9 (King James Version)", "url": "/portal/bible/Acts/9"}], "body": "Read Acts 3, Acts 4, Acts 7 and Acts 9 in the King James Version. Then read this lesson.\n\nThe early church grew in Jerusalem even though it faced opposition. Peter and John healed a man who had been lame from birth, and Peter told the crowd that it was done in the name of Jesus Christ of Nazareth. The rulers arrested them, but Peter said that there is salvation in no other name under heaven. Stephen, a man full of faith and the Holy Ghost, was chosen to serve and became the first Christian martyr when the council had him stoned. Among those who watched was a young man named Saul, who then began to persecute the church. On the road to Damascus the risen Jesus met Saul, who was changed and became the apostle Paul.\n\nKey words: lame man, name of Jesus, martyr, persecution, conversion.\n\nYour task: (1) Tell what Peter said to the lame man in Acts 3:6. (2) Say what Stephen prayed as he died. (3) Explain what happened to Saul on the road to Damascus.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "After Pentecost the church grew fast, and the apostles did signs and wonders in Jerusalem. One afternoon Peter and John went up to the temple to pray. At the gate called Beautiful a man who had been lame from birth asked them for money. Peter looked at him and said in Acts 3:6, Silver and gold have I none; but such as I have give I thee: In the name of Jesus Christ of Nazareth rise up and walk. The man leaped up, walking and praising God.\n\nThe religious leaders were troubled and had Peter and John arrested. They asked, By what power, or by what name, have ye done this? Peter, filled with the Holy Ghost, answered boldly in Acts 4:12, Neither is there salvation in any other: for there is none other name under heaven given among men, whereby we must be saved. The leaders saw that these men had been with Jesus, and they could say nothing against what had happened.\n\nAs the church grew, seven men full of the Holy Ghost were chosen to help care for the needs of the people. One of them was Stephen, who spoke with wisdom and power. He was falsely accused and brought before the council. In Acts 7 he gave a long speech that traced the story of Israel from Abraham to Jesus. The council was furious, and they dragged him out of the city and stoned him. As he died, Stephen prayed in Acts 7:60, Lord, lay not this sin to their charge. He was the first Christian martyr. A martyr is a person who dies because of faith in Jesus Christ.\n\nA young man named Saul stood by and agreed to his death. Saul then went house to house, arresting believers. But God had other plans. As Saul traveled to Damascus to arrest more Christians, a bright light from heaven shone around him, and he fell to the ground. He heard a voice say in Acts 9:4, Saul, Saul, why persecutest thou me? Saul asked who was speaking, and the voice answered that it was Jesus. Saul was blind for three days, then a believer named Ananias prayed for him, and he received his sight and was baptized. The man who persecuted the church became its greatest missionary.\n\nYour task is to tell what Peter said to the lame man, say what Stephen prayed, and explain what happened to Saul. Then take the four question check.\n\nNo one is too far gone for the grace of God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Peter, Stephen and the Conversion of Saul$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The Gospel Goes to the Gentiles$j$, $j${"readings": [{"title": "Acts 10 (King James Version)", "url": "/portal/bible/Acts/10"}, {"title": "Acts 11 (King James Version)", "url": "/portal/bible/Acts/11"}, {"title": "Acts 13 (King James Version)", "url": "/portal/bible/Acts/13"}, {"title": "Acts 15 (King James Version)", "url": "/portal/bible/Acts/15"}], "body": "Read Acts 10, Acts 11, Acts 13 and Acts 15 in the King James Version. Then read this lesson.\n\nA Gentile is a person who is not Jewish. At first nearly all believers were Jews, but God showed Peter in a vision that the good news was for everyone. Peter went to the house of Cornelius, a Roman centurion in Caesarea, and as he preached, the Holy Ghost fell on those who heard. In Antioch many Gentiles believed, and the disciples were first called Christians there. The church at Antioch sent out Barnabas and Saul on a missionary journey. Saul was also called Paul. When some said Gentile believers had to keep the law of Moses, the apostles and elders met in Jerusalem and agreed that Gentiles are saved by the grace of the Lord Jesus Christ.\n\nKey words: Gentile, Cornelius, Antioch, missionary, council.\n\nYour task: (1) Explain what a Gentile is. (2) Tell what Peter learned from the vision and the house of Cornelius (Acts 10:34 and 35). (3) Tell where believers were first called Christians.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Last time we saw Saul become a follower of Jesus. Today we see something even bigger. The good news starts to cross the line between Jews and Gentiles. A Gentile is a person who is not Jewish. Up to this point almost every believer was Jewish, and many of them did not think the Gentiles could be included.\n\nGod had to change Peter's mind. Peter was staying in Joppa when he saw a vision of a sheet let down from heaven with all kinds of animals, and a voice told him to rise, kill and eat. Peter said he had never eaten anything common or unclean. The voice said, What God hath cleansed, that call not thou common. While Peter was thinking about it, men came from a Roman centurion named Cornelius, a devout man who prayed to God and gave to the poor. An angel had told Cornelius to send for Peter.\n\nPeter went to his house in Caesarea and said in Acts 10:34 and 35, Of a truth I perceive that God is no respecter of persons: But in every nation he that feareth him, and worketh righteousness, is accepted with him. While Peter was still speaking, the Holy Ghost fell on all those who heard, and they were baptized. The door had opened to the Gentiles.\n\nIn the city of Antioch many Gentiles believed. Acts 11:26 says, the disciples were called Christians first in Antioch. The church there prayed and fasted, and the Holy Ghost said to set apart Barnabas and Saul for a special work. They traveled to Cyprus and to cities in Asia Minor and preached to Jews and Gentiles. Saul now went by his Roman name, Paul.\n\nSome men from Judaea taught that the Gentile believers had to be circumcised and keep the law of Moses. The apostles and elders gathered in Jerusalem to settle the question, and Peter reminded them that we believe that through the grace of the Lord Jesus Christ we shall be saved. The council wrote a letter to encourage the Gentile believers, and everyone rejoiced.\n\nYour task is to explain what a Gentile is, tell what Peter learned at the house of Cornelius, and tell where believers were first called Christians. Then take the four question check.\n\nThe grace of God is for every nation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The Gospel Goes to the Gentiles$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Paul's Journeys and the Witness to Rome$j$, $j${"readings": [{"title": "Acts 16 (King James Version)", "url": "/portal/bible/Acts/16"}, {"title": "Acts 17 (King James Version)", "url": "/portal/bible/Acts/17"}, {"title": "Acts 20 (King James Version)", "url": "/portal/bible/Acts/20"}, {"title": "Acts 28 (King James Version)", "url": "/portal/bible/Acts/28"}], "body": "Read Acts 16, Acts 17, Acts 20 and Acts 28 in the King James Version. Then read this lesson.\n\nThe second half of Acts follows Paul on three missionary journeys that carried the gospel across Asia Minor and Greece. At Philippi, Paul and Silas were beaten and put in prison, but at midnight they prayed and sang praises, an earthquake opened the doors, and the jailer asked what he must do to be saved. In Berea the people searched the Scriptures daily to see whether the things Paul taught were so. In Athens Paul preached on Mars' hill, and in Corinth and Ephesus churches were planted. Paul was arrested in Jerusalem, appealed to Caesar, was shipwrecked on the way, and came at last to Rome, where he preached freely for two whole years.\n\nKey words: missionary journey, Philippi, Berea, apostle, Rome.\n\nYour task: (1) Tell what Paul and Silas did at midnight in the prison at Philippi. (2) Explain why the people of Berea were called more noble (Acts 17:11). (3) Tell where the book of Acts ends and what Paul was doing there.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "We have followed the church from Jerusalem to Antioch. Now we follow Paul on his journeys. In the book of Acts Paul makes three missionary journeys, and each one carries the gospel farther. A missionary is a person sent out to tell others about Jesus.\n\nOn his second journey Paul came to Philippi, a city in Macedonia. There he and Silas were arrested, beaten with many stripes and thrown into the inner prison with their feet fast in stocks. But Acts 16:25 says, at midnight Paul and Silas prayed, and sang praises unto God: and the prisoners heard them. Suddenly there was a great earthquake, and the doors opened. The jailer was about to take his own life, but Paul called out that they were all there. The trembling jailer asked what he must do to be saved. Acts 16:31 says, Believe on the Lord Jesus Christ, and thou shalt be saved, and thy house. The jailer and his whole household were baptized that night.\n\nIn the city of Berea the Jews were glad to hear Paul. Acts 17:11 says, These were more noble than those in Thessalonica, in that they received the word with all readiness of mind, and searched the scriptures daily, whether those things were so. That is a good habit for every believer. We do not only listen to a preacher. We open the Bible and read for ourselves.\n\nIn Athens Paul stood on Mars' hill and told the philosophers about the true God who made the world. In Corinth he stayed a year and a half. On his third journey he spent about three years in Ephesus, where the word of the Lord grew mightily.\n\nPaul went back to Jerusalem, where he was arrested. He appealed to Caesar, and he sailed toward Rome. A great storm wrecked the ship on the island of Malta, but everyone on board was saved, just as God had promised. In Rome Paul lived under guard in a rented house. The last words of Acts, in chapter 28 and verse 31, say, Preaching the kingdom of God, and teaching those things which concern the Lord Jesus Christ, with all confidence, no man forbidding him. The book ends without a finished ending, because the story of the church is still being written.\n\nYour task is to tell what Paul and Silas did at midnight, explain why the people of Berea were called more noble, and tell where Acts ends. Then take the four question check and the Unit 2 quiz.\n\nOpen the Word every day, and be ready to share it anywhere. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Paul's Journeys and the Witness to Rome$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: A Witness in the Book of Acts$j$, $j${"prompt": "Choose one person from this unit: Peter, Stephen, Saul or Paul, Cornelius, or the jailer at Philippi. Write one paragraph of 150 to 200 words. Tell what happened to the person, quote at least one verse from the King James Version, and explain what the story teaches about the power of the Holy Ghost or the grace of God.", "rubric": "Total 100. Accurate account of the person and the event: 30. Quotes a King James Version verse with the reference: 20. Explains the lesson about the Holy Ghost or grace: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: A Witness in the Book of Acts$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Being a Witness Today$j$, $j${"prompt": "Jesus said we would be His witnesses. Think about the places where you spend your time, such as home, school and community. Describe one way you can be a witness for Jesus in one of those places this week. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Being a Witness Today$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Ascension and the Day of Pentecost$j$, $j${"questions": [{"q": "Who wrote the book of Acts?", "options": ["Luke", "Peter", "Paul", "John"]}, {"q": "According to Acts 1:8, what would the disciples receive when the Holy Ghost came upon them?", "options": ["Wealth", "A new law", "Power", "A king"]}, {"q": "On the day of Pentecost, what did the believers do when they were filled with the Holy Ghost?", "options": ["They left Jerusalem at once", "They spoke with other tongues as the Spirit gave them utterance", "They built a temple", "They kept silent"]}, {"q": "About how many souls were added to the church on the day Peter preached?", "options": ["Twelve", "One hundred and twenty", "Three thousand", "Five hundred"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Ascension and the Day of Pentecost$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,2}'::int[], array[$j$Luke wrote Acts as a second volume to his Gospel.$j$,$j$Jesus said they would receive power and be witnesses.$j$,$j$Acts 2:4 describes this event.$j$,$j$Acts 2:41 says about three thousand souls were added.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Ascension and the Day of Pentecost$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$, $j${"questions": [{"q": "In whose name did Peter tell the lame man to rise up and walk?", "options": ["Jesus Christ of Nazareth", "David", "Moses", "John the Baptist"]}, {"q": "What did Peter say about salvation in Acts 4:12?", "options": ["It comes through the law alone", "There is none other name under heaven whereby we must be saved", "It is found in the temple", "It is for Israel only"]}, {"q": "Who was the first Christian martyr?", "options": ["Barnabas", "Ananias", "Stephen", "James"]}, {"q": "What happened to Saul on the road to Damascus?", "options": ["He lost his way", "He was arrested", "He left for Rome", "He met the risen Jesus in a great light and was changed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,3}'::int[], array[$j$Peter said, In the name of Jesus Christ of Nazareth rise up and walk (Acts 3:6).$j$,$j$Peter declared that salvation is in the name of Jesus.$j$,$j$Stephen was stoned after he preached to the council.$j$,$j$Jesus appeared to Saul, who became the apostle Paul (Acts 9).$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Peter, Stephen and the Conversion of Saul$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Gospel Goes to the Gentiles$j$, $j${"questions": [{"q": "What is a Gentile?", "options": ["A Roman soldier", "A priest", "A person who is not Jewish", "A teacher of the law"]}, {"q": "Who was Cornelius?", "options": ["A Roman centurion in Caesarea", "A fisherman from Galilee", "A Pharisee in Jerusalem", "A prophet in Antioch"]}, {"q": "What did Peter say about God in Acts 10:34?", "options": ["God requires the law first", "God has left the earth", "God is only for Israel", "God is no respecter of persons"]}, {"q": "Where were the disciples first called Christians?", "options": ["Damascus", "Jerusalem", "Rome", "Antioch"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Gospel Goes to the Gentiles$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$A Gentile is a person who is not Jewish.$j$,$j$Cornelius was a devout Roman centurion in Caesarea (Acts 10:1 and 2).$j$,$j$Peter learned that God accepts people from every nation.$j$,$j$Acts 11:26 says they were called Christians first in Antioch.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Gospel Goes to the Gentiles$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$, $j${"questions": [{"q": "What did Paul and Silas do at midnight in the prison at Philippi?", "options": ["They wrote a letter to Rome", "They prayed and sang praises to God", "They argued with the guards", "They tried to escape"]}, {"q": "What did Paul tell the jailer to do to be saved?", "options": ["Believe on the Lord Jesus Christ", "Leave the city", "Keep the law", "Pay a fine"]}, {"q": "Why were the people of Berea called more noble?", "options": ["They were rich", "They built a synagogue", "They searched the Scriptures daily to see whether Paul's teaching was true", "They never sinned"]}, {"q": "In which city does the book of Acts end?", "options": ["Rome", "Athens", "Antioch", "Jerusalem"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,0}'::int[], array[$j$Acts 16:25 says they prayed and sang praises unto God.$j$,$j$Acts 16:31 gives this answer.$j$,$j$Acts 17:11 praises them for receiving the word and searching the Scriptures.$j$,$j$Acts ends with Paul preaching in Rome.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Paul's Journeys and the Witness to Rome$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Acts and the Early Church$j$, $j${"questions": [{"q": "What did Jesus say the disciples would be after the Holy Ghost came upon them?", "options": ["Witnesses unto Him", "Teachers of the law", "Soldiers of Rome", "Kings of Israel"]}, {"q": "What did Peter tell the crowd at Pentecost to do?", "options": ["Return to the temple", "Pay tithes", "Repent and be baptized in the name of Jesus Christ", "Leave Jerusalem"]}, {"q": "Who was stoned and became the first Christian martyr?", "options": ["Peter", "Philip", "James", "Stephen"]}, {"q": "What happened to Saul on the road to Damascus?", "options": ["He met the risen Jesus and was changed", "He saw a vision of an angel", "He was shipwrecked", "He was arrested"]}, {"q": "Where were believers first called Christians?", "options": ["Rome", "Antioch", "Corinth", "Jerusalem"]}, {"q": "Where does the book of Acts end?", "options": ["With Peter in Jerusalem", "At Pentecost", "With Stephen's death", "With Paul in Rome"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Acts and the Early Church$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,0,1,3}'::int[], array[$j$Acts 1:8 says they would be witnesses unto Him.$j$,$j$Acts 2:38 records Peter's answer.$j$,$j$Stephen died after preaching to the council (Acts 7).$j$,$j$Saul met the risen Jesus and became Paul.$j$,$j$Acts 11:26 names Antioch.$j$,$j$Acts ends with Paul preaching in Rome for two whole years.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Acts and the Early Church$j$ on conflict (item_id) do nothing;
